 CREATE OR REPLACE FUNCTION public.tb_providersearch(searchobj json)                                                                                                                                                                                                                                       
  RETURNS TABLE(totalcount bigint, providername character varying, providerfirstname character varying, providerlastname character varying, provider_id integer, taxid numeric, mail_code_tx character varying, provider_type character varying, balance_no numeric, receivable_original_amount_no numeric)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                         
 AS $function$    

 ---------------------------------------------------------------
--Revisions
-- 6/15/2026 Vinesh - CIDM-11058 Update the proc to remove tb_conv_county_codes left join which has been renamed to  tb_conv_county_codes_06172026
----------------------------------------------------------------                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                           
 DECLARE                                                                                                                                                                                                                                                                                                   
         v_Providerid INT;                                                                                                                                                                                                                                                                                 
     v_Clientid INT;                                                                                                                                                                                                                                                                                       
     v_ProviderName VARCHAR(50);                                                                                                                                                                                                                                                                           
     v_Paymentid INT;                                                                                                                                                                                                                                                                                      
     v_taxid INT;                                                                                                                                                                                                                                                                                          
     v_Firstname varchar(50);                                                                                                                                                                                                                                                                              
     v_Lastname varchar(50);                                                                                                                                                                                                                                                                               
    v_Mailcode varchar(50);                                                                                                                                                                                                                                                                                
     v_Enteredby varchar(50);                                                                                                                                                                                                                                                                              
    v_status text[];                                                                                                                                                                                                                                                                                       
     v_liPageNumber INT;                                                                                                                                                                                                                                                                                   
     v_liPageSize INT;                                                                                                                                                                                                                                                                                     
         v_pagenumber int;                                                                                                                                                                                                                                                                                 
         v_pageoffset int;                                                                                                                                                                                                                                                                                 
         v_receivable_type varchar(20);                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                           
 BEGIN                                                                                                                                                                                                                                                                                                     
 v_Providerid := searchobj ->> 'providerid';                                                                                                                                                                                                                                                               
 v_Clientid := searchobj ->> 'clientid';                                                                                                                                                                                                                                                                   
 v_ProviderName := searchobj ->> 'providername';                                                                                                                                                                                                                                                           
 v_Paymentid := searchobj ->> 'paymentid';                                                                                                                                                                                                                                                                 
 v_taxid := searchobj ->> 'taxid';                                                                                                                                                                                                                                                                         
 v_Firstname := searchobj ->> 'fname';                                                                                                                                                                                                                                                                     
 v_Lastname := searchobj ->> 'lname';                                                                                                                                                                                                                                                                      
 v_Mailcode := searchobj ->> 'mailcode';                                                                                                                                                                                                                                                                   
 v_liPageNumber := searchobj ->> 'pagenumber';                                                                                                                                                                                                                                                             
 v_liPageSize := searchobj ->> 'pagesize';                                                                                                                                                                                                                                                                 
 v_Enteredby := searchobj ->> 'enteredby';                                                                                                                                                                                                                                                                 
 v_status := searchobj ->> 'writeoffstatus';                                                                                                                                                                                                                                                               
 v_receivable_type := searchobj ->> 'receivable_type';                                                                                                                                                                                                                                                     
 raise notice 'engeredby%',v_Enteredby;                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                           
 IF COALESCE(v_liPageSize, 0) < 1 THEN                                                                                                                                                                                                                                                                     
         v_liPageSize := 10;                                                                                                                                                                                                                                                                               
 END IF;                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                           
 IF COALESCE(v_liPageNumber, 0) < 1                                                                                                                                                                                                                                                                        
 THEN                                                                                                                                                                                                                                                                                                      
         v_liPageNumber := 1;                                                                                                                                                                                                                                                                              
 end if;                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                           
 v_pagenumber := v_liPageNumber - 1;                                                                                                                                                                                                                                                                       
 v_pageoffset := v_pagenumber * v_liPageSize;                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                           
 if(v_receivable_type = 'System')                                                                                                                                                                                                                                                                          
 then                                                                                                                                                                                                                                                                                                      
 return query                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                           
 select count(1) over() as totalcount,(CASE WHEN (tp.provider_nm is null OR tp.provider_nm='') THEN CONCAT(tp.provider_first_nm,' ',tp.provider_last_nm) ELSE tp.provider_nm END) as providername,tp.provider_first_nm as providerfirstname,tp.provider_last_nm as providerlastname,                       
 tp.provider_id,tp.tax_id_no as taxid                                                                                                                                                                                                                                                                      
 ,tp.mail_code_tx AS     mail_code_tx                                                                                                                                                                                                                                                                      
 --,trd.receivable_detail_id,trd.receivable_ts as dateidentified, trd.start_dt as fromdate, trd.end_dt as todate,trd.amount_no as overpaymentamount,                                                                                                                                                       
 --trd.receivable_balance_no as balance,tpd.client_id, concat (p.firstname, ' ',p.lastname) as clientname, tccc.county_name,                                                                                                                                                                               
 ,(select value_tx from tb_picklist_values where PICKLIST_type_id=155 AND delete_sw='N'                                                                                                                                                                                                                    
 AND active_sw='Y' AND  TRIM(PICKLIST_VALUE_CD)=TRIM(tp.provider_category_cd)) AS  providertype,                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                           
 (select sum(trdd.amount_no) from tb_receivable_detail trdd                                                                                                                                                                                                                                                
 join tb_receivable_header ttrh on ttrh.receivable_id=trdd.receivable_id                                                                                                                                                                                                                                   
 join tb_provider tp on tp.provider_id =ttrh.provider_id where tp.provider_id=  tp.provider_id                                                                                                                                                                                                             
 ) as balance_no,                                                                                                                                                                                                                                                                                          
 (                                                                                                                                                                                                                                                                                                         
 select sum(trdd.receivable_balance_no) from tb_receivable_detail trdd                                                                                                                                                                                                                                     
 join tb_receivable_header ttrh on ttrh.receivable_id=trdd.receivable_id                                                                                                                                                                                                                                   
 join tb_provider tp on tp.provider_id =ttrh.provider_id where tp.provider_id=  tp.provider_id                                                                                                                                                                                                             
 ) as receivable_original_amount_no                                                                                                                                                                                                                                                                        
 from tb_provider tp                                                                                                                                                                                                                                                                                       
   join tb_receivable_header trh on trh.provider_id = tp.provider_id                                                                                                                                                                                                                                       
   join tb_receivable_detail trd on trd.receivable_id = trh.receivable_id                                                                                                                                                                                                                                  
  left join tb_payment_detail tpd on tpd.payment_detail_id = trd.payment_detail_id                                                                                                                                                                                                                         
  left join person p on p.cjamspid = tpd.client_id                                                                                                                                                                                                                                                         
 left join tb_county_unit tcu on tcu.county_cd = tp.county_cd                                                                                                                                                                                                                                              
 --left  join tb_conv_county_codes tccc on tccc.county_code = tcu.county_cd                                                                                                                                                                                                                                  
 left join userprofile up on up.securityusersid = v_Enteredby                                                                                                                                                                                                                                              
 where (v_Providerid is null or tp.provider_id=v_Providerid)                                                                                                                                                                                                                                               
 and (v_Clientid is null or tpd.client_id=v_Clientid)                                                                                                                                                                                                                                                      
 --AND (COALESCE(lower(tp.provider_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')                                                                                                                                                                                                                 
 and (case when tp.provider_nm is not null then (COALESCE(lower(tp.provider_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')                                                                                                                                                                        
           when tp.provider_nm is  null  then  ((COALESCE(lower(tp.provider_first_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%') or  (COALESCE(lower(tp.provider_last_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')) or                                                                 
           (COALESCE(lower(concat (tp.provider_first_nm,' ',tp.provider_last_nm)) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%') end )                                                                                                                                                                
 and (v_Paymentid is null or tpd.payment_id=v_Paymentid)                                                                                                                                                                                                                                                   
 and (v_taxid is null or tp.tax_id_no=v_taxid)                                                                                                                                                                                                                                                             
 AND (COALESCE(lower(tp.provider_first_nm) ,'') LIKE COALESCE(lower(v_Firstname) ,'')||'%')                                                                                                                                                                                                                
 AND (COALESCE(lower(tp.provider_last_nm) ,'') LIKE COALESCE(lower(v_Lastname) ,'')||'%')                                                                                                                                                                                                                  
 and (v_Mailcode is null or tp.mail_code_tx=v_Mailcode)                                                                                                                                                                                                                                                    
 and (v_status is null or trd.write_off_approval_status= ANY (v_status))                                                                                                                                                                                                                                   
 group by providername, providerfirstname, providerlastname,                                                                                                                                                                                                                                               
 tp.provider_id,tp.tax_id_no,providertype,tp.mail_code_tx                                                                                                                                                                                                                                                  
 LIMIT v_liPageSize OFFSET v_pageoffset;                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                           
 else if(v_receivable_type = 'Manual')                                                                                                                                                                                                                                                                     
 then                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                           
 return query                                                                                                                                                                                                                                                                                              
         select count(1) over() as totalcount,(CASE WHEN (prov.provider_nm is null OR prov.provider_nm='') THEN CONCAT(prov.provider_first_nm,' ',prov.provider_last_nm) ELSE prov.provider_nm END) as providername,prov.provider_first_nm as providerfirstname,prov.provider_last_nm as providerlastname, 
 prov.provider_id,prov.tax_id_no as taxid                                                                                                                                                                                                                                                                  
 ,prov.mail_code_tx AS     mail_code_tx                                                                                                                                                                                                                                                                    
 --,trd.receivable_detail_id,trd.receivable_ts as dateidentified, trd.start_dt as fromdate, trd.end_dt as todate,trd.amount_no as overpaymentamount,                                                                                                                                                       
 --trd.receivable_balance_no as balance,tpd.client_id, concat (p.firstname, ' ',p.lastname) as clientname, tccc.county_name,                                                                                                                                                                               
 ,(select value_tx from tb_picklist_values where PICKLIST_type_id=155 AND delete_sw='N'                                                                                                                                                                                                                    
 AND active_sw='Y' AND  TRIM(PICKLIST_VALUE_CD)=TRIM(prov.provider_category_cd)) AS  providertype,                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                           
 (select sum(trdd.amount_no) from tb_receivable_detail trdd                                                                                                                                                                                                                                                
 join tb_receivable_header ttrh on ttrh.receivable_id=trdd.receivable_id                                                                                                                                                                                                                                   
 join tb_provider tp on prov.provider_id =ttrh.provider_id where prov.provider_id=  prov.provider_id                                                                                                                                                                                                       
 ) as balance_no,                                                                                                                                                                                                                                                                                          
 (                                                                                                                                                                                                                                                                                                         
 select sum(trdd.receivable_balance_no) from tb_receivable_detail trdd                                                                                                                                                                                                                                     
 join tb_receivable_header ttrh on ttrh.receivable_id=trdd.receivable_id                                                                                                                                                                                                                                   
 join tb_provider tp on prov.provider_id =ttrh.provider_id where prov.provider_id=  prov.provider_id                                                                                                                                                                                                       
 ) as receivable_original_amount_no                                                                                                                                                                                                                                                                        
 from tb_payment_header as payhead                                                                                                                                                                                                                                                                         
 inner join tb_payment_detail as paydet on                                                                                                                                                                                                                                                                 
         payhead.payment_id = paydet.payment_id                                                                                                                                                                                                                                                            
         --INNER JOIN tb_payment_detail_temp as paydettemp ON payhead.payment_id = paydettemp.payment_id                                                                                                                                                                                                   
 inner join person as client on                                                                                                                                                                                                                                                                            
         paydet.client_id = client.cjamspid                                                                                                                                                                                                                                                                
 inner join tb_provider as prov on                                                                                                                                                                                                                                                                         
         payhead.provider_id = prov.provider_id                                                                                                                                                                                                                                                            
 inner join tb_payment_status paystat on                                                                                                                                                                                                                                                                   
         payhead.payment_id = paystat.payment_id                                                                                                                                                                                                                                                           
         and paystat.delete_sw = 'N'                                                                                                                                                                                                                                                                       
 left join tb_service_purchase_authorization payauth on                                                                                                                                                                                                                                                    
         payauth.authorization_id = payhead.authorization_id                                                                                                                                                                                                                                               
         and payauth.delete_sw = 'N'                                                                                                                                                                                                                                                                       
   left join tb_receivable_header trh on trh.provider_id = prov.provider_id                                                                                                                                                                                                                                
   left join tb_receivable_detail trd on trd.receivable_id = trh.receivable_id                                                                                                                                                                                                                             
  -- join tb_payment_status tps on tps.payment_id = th.payment_id and tps.approval_status_cd ='3047' and tps.delete_sw ='N'                                                                                                                                                                                
 -- left join person p on p.cjamspid = paydet.client_id                                                                                                                                                                                                                                                    
 left join tb_county_unit tcu on tcu.county_cd = prov.county_cd                                                                                                                                                                                                                                            
 --left  join tb_conv_county_codes tccc on tccc.county_code = tcu.county_cd                                                                                                                                                                                                                                  
 --left join userprofile up on up.securityusersid = v_Enteredby                                                                                                                                                                                                                                            
 where                                                                                                                                                                                                                                                                                                     
 payhead.payment_type_cd = '4'                                                                                                                                                                                                                                                                             
  and (v_Providerid is null or prov.provider_id=v_Providerid)                                                                                                                                                                                                                                              
 and (v_Clientid is null or paydet.client_id=v_Clientid)                                                                                                                                                                                                                                                   
 --AND (COALESCE(lower(prov.provider_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')                                                                                                                                                                                                               
 and (case when prov.provider_nm is not null then (COALESCE(lower(prov.provider_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')                                                                                                                                                                    
           when prov.provider_nm is  null  then  ((COALESCE(lower(prov.provider_first_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%') or  (COALESCE(lower(prov.provider_last_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')) or                                                           
           (COALESCE(lower(concat (prov.provider_first_nm,' ',prov.provider_last_nm)) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%') end )                                                                                                                                                            
 and (v_Paymentid is null or paydet.payment_id=v_Paymentid)                                                                                                                                                                                                                                                
 and (v_taxid is null or prov.tax_id_no=v_taxid)                                                                                                                                                                                                                                                           
 AND (COALESCE(lower(prov.provider_first_nm) ,'') LIKE COALESCE(lower(v_Firstname) ,'')||'%')                                                                                                                                                                                                              
 AND (COALESCE(lower(prov.provider_last_nm) ,'') LIKE COALESCE(lower(v_Lastname) ,'')||'%')                                                                                                                                                                                                                
 and (v_Mailcode is null or prov.mail_code_tx=v_Mailcode)                                                                                                                                                                                                                                                  
 and (v_status is null or trd.write_off_approval_status= ANY (v_status))                                                                                                                                                                                                                                   
 group by providername, providerfirstname, providerlastname,                                                                                                                                                                                                                                               
 prov.provider_id,prov.tax_id_no,providertype,prov.mail_code_tx                                                                                                                                                                                                                                            
 LIMIT v_liPageSize OFFSET v_pageoffset;                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                           
 else                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                           
 return query                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                           
 select count(1) over() ,x.*  from                                                                                                                                                                                                                                                                         
 ((                                                                                                                                                                                                                                                                                                        
 select (CASE WHEN (tp.provider_nm is null OR tp.provider_nm='') THEN CONCAT(tp.provider_first_nm,' ',tp.provider_last_nm) ELSE tp.provider_nm END) as providername,tp.provider_first_nm as providerfirstname,tp.provider_last_nm as providerlastname,                                                     
 tp.provider_id,tp.tax_id_no as taxid                                                                                                                                                                                                                                                                      
 ,tp.mail_code_tx AS     mail_code_tx                                                                                                                                                                                                                                                                      
 --,trd.receivable_detail_id,trd.receivable_ts as dateidentified, trd.start_dt as fromdate, trd.end_dt as todate,trd.amount_no as overpaymentamount,                                                                                                                                                       
 --trd.receivable_balance_no as balance,tpd.client_id, concat (p.firstname, ' ',p.lastname) as clientname, tccc.county_name,                                                                                                                                                                               
 ,(select value_tx from tb_picklist_values where PICKLIST_type_id=155 AND delete_sw='N'                                                                                                                                                                                                                    
 AND active_sw='Y' AND  TRIM(PICKLIST_VALUE_CD)=TRIM(tp.provider_category_cd)) AS  providertype,                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                           
 (select sum(trdd.amount_no) from tb_receivable_detail trdd                                                                                                                                                                                                                                                
 join tb_receivable_header ttrh on ttrh.receivable_id=trdd.receivable_id                                                                                                                                                                                                                                   
 join tb_provider tp on tp.provider_id =ttrh.provider_id where tp.provider_id=  tp.provider_id                                                                                                                                                                                                             
 ) as balance_no,                                                                                                                                                                                                                                                                                          
 (                                                                                                                                                                                                                                                                                                         
 select sum(trdd.receivable_balance_no) from tb_receivable_detail trdd                                                                                                                                                                                                                                     
 join tb_receivable_header ttrh on ttrh.receivable_id=trdd.receivable_id                                                                                                                                                                                                                                   
 join tb_provider tp on tp.provider_id =ttrh.provider_id where tp.provider_id=  tp.provider_id                                                                                                                                                                                                             
 ) as receivable_original_amount_no                                                                                                                                                                                                                                                                        
 from tb_provider tp                                                                                                                                                                                                                                                                                       
   join tb_receivable_header trh on trh.provider_id = tp.provider_id                                                                                                                                                                                                                                       
   join tb_receivable_detail trd on trd.receivable_id = trh.receivable_id                                                                                                                                                                                                                                  
  left join tb_payment_detail tpd on tpd.payment_detail_id = trd.payment_detail_id                                                                                                                                                                                                                         
  left join person p on p.cjamspid = tpd.client_id                                                                                                                                                                                                                                                         
 left join tb_county_unit tcu on tcu.county_cd = tp.county_cd                                                                                                                                                                                                                                              
 --left  join tb_conv_county_codes tccc on tccc.county_code = tcu.county_cd                                                                                                                                                                                                                                  
 left join userprofile up on up.securityusersid = v_Enteredby                                                                                                                                                                                                                                              
 where (v_Providerid is null or tp.provider_id=v_Providerid)                                                                                                                                                                                                                                               
 and (v_Clientid is null or tpd.client_id=v_Clientid)                                                                                                                                                                                                                                                      
 --AND (COALESCE(lower(tp.provider_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')                                                                                                                                                                                                                 
 and (case when tp.provider_nm is not null then (COALESCE(lower(tp.provider_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')                                                                                                                                                                        
           when tp.provider_nm is  null  then  ((COALESCE(lower(tp.provider_first_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%') or  (COALESCE(lower(tp.provider_last_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')) or                                                                 
           (COALESCE(lower(concat (tp.provider_first_nm,' ',tp.provider_last_nm)) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%') end )                                                                                                                                                                
 and (v_Paymentid is null or tpd.payment_id=v_Paymentid)                                                                                                                                                                                                                                                   
 and (v_taxid is null or tp.tax_id_no=v_taxid)                                                                                                                                                                                                                                                             
 AND (COALESCE(lower(tp.provider_first_nm) ,'') LIKE COALESCE(lower(v_Firstname) ,'')||'%')                                                                                                                                                                                                                
 AND (COALESCE(lower(tp.provider_last_nm) ,'') LIKE COALESCE(lower(v_Lastname) ,'')||'%')                                                                                                                                                                                                                  
 and (v_Mailcode is null or tp.mail_code_tx=v_Mailcode)                                                                                                                                                                                                                                                    
 and (v_status is null or trd.write_off_approval_status= ANY (v_status))                                                                                                                                                                                                                                   
 group by providername, providerfirstname, providerlastname,                                                                                                                                                                                                                                               
 tp.provider_id,tp.tax_id_no,providertype,tp.mail_code_tx                                                                                                                                                                                                                                                  
 )                                                                                                                                                                                                                                                                                                         
 union all                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                           
 (select (CASE WHEN (prov.provider_nm is null OR prov.provider_nm='') THEN CONCAT(prov.provider_first_nm,' ',prov.provider_last_nm) ELSE prov.provider_nm END) as providername,prov.provider_first_nm as providerfirstname,prov.provider_last_nm as providerlastname,                                      
 prov.provider_id,prov.tax_id_no as taxid                                                                                                                                                                                                                                                                  
 ,prov.mail_code_tx AS     mail_code_tx                                                                                                                                                                                                                                                                    
 --,trd.receivable_detail_id,trd.receivable_ts as dateidentified, trd.start_dt as fromdate, trd.end_dt as todate,trd.amount_no as overpaymentamount,                                                                                                                                                       
 --trd.receivable_balance_no as balance,tpd.client_id, concat (p.firstname, ' ',p.lastname) as clientname, tccc.county_name,                                                                                                                                                                               
 ,(select value_tx from tb_picklist_values where PICKLIST_type_id=155 AND delete_sw='N'                                                                                                                                                                                                                    
 AND active_sw='Y' AND  TRIM(PICKLIST_VALUE_CD)=TRIM(prov.provider_category_cd)) AS  providertype,                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                           
 (select sum(trdd.amount_no) from tb_receivable_detail trdd                                                                                                                                                                                                                                                
 join tb_receivable_header ttrh on ttrh.receivable_id=trdd.receivable_id                                                                                                                                                                                                                                   
 join tb_provider tp on prov.provider_id =ttrh.provider_id where prov.provider_id=  prov.provider_id                                                                                                                                                                                                       
 ) as balance_no,                                                                                                                                                                                                                                                                                          
 (                                                                                                                                                                                                                                                                                                         
 select sum(trdd.receivable_balance_no) from tb_receivable_detail trdd                                                                                                                                                                                                                                     
 join tb_receivable_header ttrh on ttrh.receivable_id=trdd.receivable_id                                                                                                                                                                                                                                   
 join tb_provider tp on prov.provider_id =ttrh.provider_id where prov.provider_id=  prov.provider_id                                                                                                                                                                                                       
 ) as receivable_original_amount_no                                                                                                                                                                                                                                                                        
 from tb_payment_header as payhead                                                                                                                                                                                                                                                                         
 inner join tb_payment_detail as paydet on                                                                                                                                                                                                                                                                 
         payhead.payment_id = paydet.payment_id                                                                                                                                                                                                                                                            
         --INNER JOIN tb_payment_detail_temp as paydettemp ON payhead.payment_id = paydettemp.payment_id                                                                                                                                                                                                   
 inner join person as client on                                                                                                                                                                                                                                                                            
         paydet.client_id = client.cjamspid                                                                                                                                                                                                                                                                
 inner join tb_provider as prov on                                                                                                                                                                                                                                                                         
         payhead.provider_id = prov.provider_id                                                                                                                                                                                                                                                            
 inner join tb_payment_status paystat on                                                                                                                                                                                                                                                                   
         payhead.payment_id = paystat.payment_id                                                                                                                                                                                                                                                           
         and paystat.delete_sw = 'N'                                                                                                                                                                                                                                                                       
 left join tb_service_purchase_authorization payauth on                                                                                                                                                                                                                                                    
         payauth.authorization_id = payhead.authorization_id                                                                                                                                                                                                                                               
         and payauth.delete_sw = 'N'                                                                                                                                                                                                                                                                       
   left join tb_receivable_header trh on trh.provider_id = prov.provider_id                                                                                                                                                                                                                                
   left join tb_receivable_detail trd on trd.receivable_id = trh.receivable_id                                                                                                                                                                                                                             
  -- join tb_payment_status tps on tps.payment_id = th.payment_id and tps.approval_status_cd ='3047' and tps.delete_sw ='N'                                                                                                                                                                                
 -- left join person p on p.cjamspid = paydet.client_id                                                                                                                                                                                                                                                    
 left join tb_county_unit tcu on tcu.county_cd = prov.county_cd                                                                                                                                                                                                                                            
 --left  join tb_conv_county_codes tccc on tccc.county_code = tcu.county_cd                                                                                                                                                                                                                                  
 --left join userprofile up on up.securityusersid = v_Enteredby                                                                                                                                                                                                                                            
 where                                                                                                                                                                                                                                                                                                     
 payhead.payment_type_cd = '4'                                                                                                                                                                                                                                                                             
  and (v_Providerid is null or prov.provider_id=v_Providerid)                                                                                                                                                                                                                                              
 and (v_Clientid is null or paydet.client_id=v_Clientid)                                                                                                                                                                                                                                                   
 --AND (COALESCE(lower(prov.provider_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')                                                                                                                                                                                                               
 and (case when prov.provider_nm is not null then (COALESCE(lower(prov.provider_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')                                                                                                                                                                    
           when prov.provider_nm is  null  then  ((COALESCE(lower(prov.provider_first_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%') or  (COALESCE(lower(prov.provider_last_nm) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%')) or                                                           
           (COALESCE(lower(concat (prov.provider_first_nm,' ',prov.provider_last_nm)) ,'') LIKE COALESCE(lower(v_ProviderName) ,'')||'%') end )                                                                                                                                                            
 and (v_Paymentid is null or paydet.payment_id=v_Paymentid)                                                                                                                                                                                                                                                
 and (v_taxid is null or prov.tax_id_no=v_taxid)                                                                                                                                                                                                                                                           
 AND (COALESCE(lower(prov.provider_first_nm) ,'') LIKE COALESCE(lower(v_Firstname) ,'')||'%')                                                                                                                                                                                                              
 AND (COALESCE(lower(prov.provider_last_nm) ,'') LIKE COALESCE(lower(v_Lastname) ,'')||'%')                                                                                                                                                                                                                
 and (v_Mailcode is null or prov.mail_code_tx=v_Mailcode)                                                                                                                                                                                                                                                  
 and (v_status is null or trd.write_off_approval_status= ANY (v_status))                                                                                                                                                                                                                                   
 group by providername, providerfirstname, providerlastname,                                                                                                                                                                                                                                               
 prov.provider_id,prov.tax_id_no,providertype,prov.mail_code_tx )                                                                                                                                                                                                                                          
 ) as x                                                                                                                                                                                                                                                                                                    
 group by x.receivable_original_amount_no,x.balance_no, x.providername, x.providerfirstname, x.providerlastname,                                                                                                                                                                                           
 x.provider_id,x.taxid,x.providertype,x.mail_code_tx                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                           
 LIMIT v_liPageSize OFFSET v_pageoffset;                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                           
 end if;                                                                                                                                                                                                                                                                                                   
 end if;                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                           
 END;                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                           
 $function$                                                                                                                                                                                                                                                                                                

